/**
 * Resolves destination hero/card image dynamically for ANY Pakistani destination
 */
export function getDestinationImage(destination) {
  if (!destination) return DESTINATION_IMAGES.islamabad.hero

  const lower = String(destination).toLowerCase().trim()
  
  // 1. Direct city and destination keyword matching
  if (lower.includes('hunza') || lower.includes('karimabad') || lower.includes('passu') || lower.includes('attabad')) return DESTINATION_IMAGES.hunza.hero
  if (lower.includes('skardu') || lower.includes('shangrila') || lower.includes('deosai') || lower.includes('kachura')) return DESTINATION_IMAGES.skardu.hero
  if (lower.includes('murree') || lower.includes('galyat') || lower.includes('nathia') || lower.includes('patriata') || lower.includes('ayubia') || lower.includes('bhurban')) return DESTINATION_IMAGES.murree.hero
  if (lower.includes('lahore') || lower.includes('badshahi') || lower.includes('shalimar') || lower.includes('anarkali')) return DESTINATION_IMAGES.lahore.hero
  if (lower.includes('swat') || lower.includes('kalam') || lower.includes('malam') || lower.includes('fizagat') || lower.includes('mingora')) return DESTINATION_IMAGES.swat.hero
  if (lower.includes('karachi') || lower.includes('clifton') || lower.includes('saddar') || lower.includes('manora') || lower.includes('kemari')) return DESTINATION_IMAGES.karachi.hero
  if (lower.includes('peshawar') || lower.includes('khyber') || lower.includes('qissa')) return DESTINATION_IMAGES.peshawar.hero
  if (lower.includes('bahawalpur') || lower.includes('cholistan') || lower.includes('derawar') || lower.includes('noor mahal')) return DESTINATION_IMAGES.bahawalpur.hero
  if (lower.includes('multan') || lower.includes('rukn-e-alam') || lower.includes('bahauddin')) return DESTINATION_IMAGES.multan.hero
  if (lower.includes('quetta') || lower.includes('ziarat') || lower.includes('hanna')) return DESTINATION_IMAGES.quetta.hero
  if (lower.includes('faisalabad') || lower.includes('ghanta') || lower.includes('lyallpur')) return DESTINATION_IMAGES.faisalabad.hero
  if (lower.includes('hyderabad') || lower.includes('kotri') || lower.includes('pacco')) return DESTINATION_IMAGES.hyderabad.hero
  if (lower.includes('gilgit') || lower.includes('naltar')) return DESTINATION_IMAGES.gilgit.hero
  if (lower.includes('rawalpindi') || lower.includes('pindi') || lower.includes('ayub park')) return DESTINATION_IMAGES.rawalpindi?.hero || DESTINATION_IMAGES.islamabad.hero
  if (lower.includes('gwadar') || lower.includes('makran') || lower.includes('ormara') || lower.includes('pasni')) return DESTINATION_IMAGES.gwadar?.hero || DESTINATION_IMAGES.karachi.hero
  if (lower.includes('naran') || lower.includes('kaghan') || lower.includes('saif') || lower.includes('babusar')) return DESTINATION_IMAGES.naran?.hero || DESTINATION_IMAGES.swat.hero
  if (lower.includes('chitral') || lower.includes('kalash') || lower.includes('shandur')) return DESTINATION_IMAGES.chitral?.hero || DESTINATION_IMAGES.hunza.hero
  if (lower.includes('abbottabad') || lower.includes('thandiani') || lower.includes('shimla')) return DESTINATION_IMAGES.abbottabad?.hero || DESTINATION_IMAGES.murree.hero
  if (lower.includes('neelum') || lower.includes('muzaffarabad') || lower.includes('arang') || lower.includes('sharda') || lower.includes('kashmir')) return DESTINATION_IMAGES.neelum?.hero || DESTINATION_IMAGES.hunza.hero
  if (lower.includes('sukkur') || lower.includes('rohri') || lower.includes('kot diji')) return DESTINATION_IMAGES.sukkur?.hero || DESTINATION_IMAGES.hyderabad.hero
  if (lower.includes('sialkot') || lower.includes('iqbal manzil')) return DESTINATION_IMAGES.sialkot?.hero || DESTINATION_IMAGES.lahore.hero
  if (lower.includes('gujranwala') || lower.includes('nishan-e-manzil')) return DESTINATION_IMAGES.gujranwala?.hero || DESTINATION_IMAGES.lahore.hero
  if (lower.includes('chakwal') || lower.includes('kallar kahar')) return DESTINATION_IMAGES.chakwal?.hero || DESTINATION_IMAGES.islamabad.hero
  if (lower.includes('thatta') || lower.includes('makli') || lower.includes('keenjhar')) return DESTINATION_IMAGES.thatta?.hero || DESTINATION_IMAGES.karachi.hero
  if (lower.includes('ziarat')) return DESTINATION_IMAGES.ziarat?.hero || DESTINATION_IMAGES.quetta.hero
  if (lower.includes('kumrat') || lower.includes('jahaz banda')) return DESTINATION_IMAGES.kumrat?.hero || DESTINATION_IMAGES.swat.hero
  if (lower.includes('khaplu') || lower.includes('shigar')) return DESTINATION_IMAGES.khaplu?.hero || DESTINATION_IMAGES.skardu.hero
  if (lower.includes('deosai')) return DESTINATION_IMAGES.deosai?.hero || DESTINATION_IMAGES.skardu.hero
  if (lower.includes('fairy meadows') || lower.includes('fairymeadows')) return DESTINATION_IMAGES.fairymeadows?.hero || DESTINATION_IMAGES.skardu.hero
  if (lower.includes('passu') || lower.includes('gulmit')) return DESTINATION_IMAGES.passu?.hero || DESTINATION_IMAGES.hunza.hero
  if (lower.includes('khunjerab')) return DESTINATION_IMAGES.khunjerab?.hero || DESTINATION_IMAGES.hunza.hero
  if (lower.includes('astore') || lower.includes('rama')) return DESTINATION_IMAGES.astore?.hero || DESTINATION_IMAGES.gilgit.hero
  if (lower.includes('phander') || lower.includes('ghizer')) return DESTINATION_IMAGES.phander?.hero || DESTINATION_IMAGES.gilgit.hero
  if (lower.includes('hingol') || lower.includes('kund malir')) return DESTINATION_IMAGES.hingol?.hero || DESTINATION_IMAGES.gwadar?.hero || DESTINATION_IMAGES.karachi.hero
  if (lower.includes('muzaffarabad') || lower.includes('pir chinasi')) return DESTINATION_IMAGES.muzaffarabad?.hero || DESTINATION_IMAGES.neelum?.hero
  if (lower.includes('rawalakot') || lower.includes('banjosa') || lower.includes('toli pir')) return DESTINATION_IMAGES.rawalakot?.hero || DESTINATION_IMAGES.neelum?.hero
  if (lower.includes('leepa')) return DESTINATION_IMAGES.leepa?.hero || DESTINATION_IMAGES.neelum?.hero
  if (lower.includes('taxila') || lower.includes('dharmarajika') || lower.includes('jaulian')) return DESTINATION_IMAGES.taxila?.hero || DESTINATION_IMAGES.islamabad.hero
  if (lower.includes('larkana') || lower.includes('mohenjo')) return DESTINATION_IMAGES.larkana?.hero || DESTINATION_IMAGES.karachi.hero
  if (lower.includes('islamabad') || lower.includes('margalla') || lower.includes('rawal')) return DESTINATION_IMAGES.islamabad.hero

  // 2. Check if destination corresponds to an authentic verified Pakistan landmark
  const landmarkMatch = findVerifiedLandmark('', destination, '')
  if (landmarkMatch && landmarkMatch.imageUrl) {
    return landmarkMatch.imageUrl
  }

  // 3. Check regional provinces
  if (lower.includes('balochistan')) return DESTINATION_IMAGES.quetta.hero
  if (lower.includes('baltistan') || lower.includes('karakoram')) return DESTINATION_IMAGES.skardu.hero
  if (lower.includes('kpk') || lower.includes('pakhtunkhwa')) return DESTINATION_IMAGES.swat.hero
  if (lower.includes('sindh')) return DESTINATION_IMAGES.karachi.hero
  if (lower.includes('punjab')) return DESTINATION_IMAGES.lahore.hero

  // Default to Islamabad capital
  return DESTINATION_IMAGES.islamabad.hero
}

