/**
 * Resolves place/stop photo based on ID, category, or title.
 * Strictly avoids assigning unrelated landmarks or mountains as fallbacks for mosques/monuments.
 */
export function getPlaceImage(placeId, category = 'attraction', placeTitle = '', destination = '') {
  // 1. Direct ID match in PLACE_IMAGES
  if (placeId && PLACE_IMAGES[placeId]) {
    return PLACE_IMAGES[placeId]
  }

  // 2. Query Central Authentic Image Architecture (sync)
  const authentic = getAuthenticPlaceImageSync(placeId, category, placeTitle, destination)
  if (authentic && authentic.imageUrl) {
    return authentic.imageUrl
  }

  // 3. Fallback to category-appropriate placeholder (no scenic mountain for historic/religious places)
  const catKey = (category || 'default').toLowerCase()
  const titleLow = String(placeTitle || '').toLowerCase()
  if (titleLow.includes('mosque') || titleLow.includes('masjid') || catKey.includes('mosque') || catKey.includes('religious')) {
    return CATEGORY_FALLBACK_IMAGES.mosque
  }
  if (titleLow.includes('fort') || titleLow.includes('palace') || titleLow.includes('tomb') || catKey.includes('historic') || catKey.includes('monument')) {
    return CATEGORY_FALLBACK_IMAGES.historic
  }
  if (titleLow.includes('museum') || catKey.includes('museum')) {
    return CATEGORY_FALLBACK_IMAGES.museum
  }
  if (titleLow.includes('park') || titleLow.includes('garden') || catKey.includes('park')) {
    return CATEGORY_FALLBACK_IMAGES.park
  }
  if (titleLow.includes('beach') || catKey.includes('beach')) {
    return CATEGORY_FALLBACK_IMAGES.beach
  }
  if (titleLow.includes('lake') || catKey.includes('lake') || catKey.includes('scenic')) {
    return CATEGORY_FALLBACK_IMAGES.scenic
  }
  return CATEGORY_FALLBACK_IMAGES[catKey] || CATEGORY_FALLBACK_IMAGES.default
}

